(function(){
      var video=document.currentScript.previousElementSibling;
      var motion=window.matchMedia('(prefers-reduced-motion: reduce)');
      function syncHeroMotion(){
        if(motion.matches){
          video.pause();
          return;
        }
        var playRequest=video.play();
        if(playRequest&&typeof playRequest.catch==='function')playRequest.catch(function(){});
      }
      syncHeroMotion();
      if(typeof motion.addEventListener==='function')motion.addEventListener('change',syncHeroMotion);
      else if(typeof motion.addListener==='function')motion.addListener(syncHeroMotion);
    })();










